The five DfT traffic indicators (`count_point_n`, `mean_aadf_*`) are missing for 267 of 343 LSOAs (78%). DfT count points are placed on strategic roads. Most residential LSOAs simply have no count point within their boundary, so `NA` genuinely means *unmeasured*, not zero.


::: {.cell}

```{.r .cell-code}
tar_load(sf_lsoa)

sf_lsoa_count_point <- sf_lsoa |>
  st_transform(4326) |>
  left_join(df_lsoa_all |> select(LSOA21CD, count_point_n), by = "LSOA21CD") |>
  mutate(
    has_traffic = !is.na(count_point_n),
    fill_colour = if_else(has_traffic, "#2166ac", "#ff964f")
  )

bb <- sf_lsoa_count_point |> st_bbox()

make_basemap() |>
  fitBounds(bb[["xmin"]], bb[["ymin"]], bb[["xmax"]], bb[["ymax"]]) |>
  addPolygons(
    data        = sf_lsoa_count_point,
    fillColor   = ~fill_colour,
    fillOpacity = 0.6,
    color       = "white",
    weight      = 0.5,
    smoothFactor = 0.5
  ) |>
  addLegend(
    position = "topright",
    colors   = c("#2166ac", "#ff964f"),
    labels   = c("Count point present", "No count point"),
    opacity  = 0.6,
    title    = NULL
  )
```

